import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Day 19: Kernel Configuration & Fragments (.cfg)","description":"","frontmatter":{},"headers":[],"relativePath":"day19-kernel-configuration-menuconfig.md","filePath":"day19-kernel-configuration-menuconfig.md"}'),s={name:"day19-kernel-configuration-menuconfig.md"};function o(r,e,l,c,d,p){return i(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="day-19-kernel-configuration-fragments-cfg" tabindex="-1">Day 19: Kernel Configuration &amp; Fragments (.cfg) <a class="header-anchor" href="#day-19-kernel-configuration-fragments-cfg" aria-label="Permalink to &quot;Day 19: Kernel Configuration &amp; Fragments (.cfg)&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Explain the role of <code>virtual/kernel</code> in Yocto</li><li>Launch and navigate the Linux Kernel <code>menuconfig</code> graphical interface</li><li>Enable or disable kernel modules and built-in drivers (<code>=m</code> vs <code>=y</code>)</li><li>Create Configuration Fragments (<code>.cfg</code>) and apply them via a <code>.bbappend</code></li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day18-device-trees-dts-dtb-dtc.html">Day 18: Device Trees (DTS/DTB)</a></li></ul></div><hr><h2 id="_1-the-kernel-virtual-provider" tabindex="-1">1. The Kernel Virtual Provider <a class="header-anchor" href="#_1-the-kernel-virtual-provider" aria-label="Permalink to &quot;1. The Kernel Virtual Provider&quot;">​</a></h2><p>Different hardware platforms require vastly different Linux kernels. If you build for QEMU, Yocto uses the <code>linux-yocto</code> recipe. If you build for the BeagleBone, it uses <code>linux-ti-staging</code>. If you build for the Raspberry Pi, it uses <code>linux-raspberrypi</code>.</p><p>To prevent every image recipe from hardcoding the specific kernel name, Yocto uses a <strong>virtual provider</strong>.</p><p>Image recipes simply depend on <code>virtual/kernel</code>. Your <code>local.conf</code> or machine definition file (<code>raspberrypi4.conf</code>) tells BitBake which actual recipe satisfies <code>virtual/kernel</code> for that specific machine:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Example from a machine.conf file</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PREFERRED_PROVIDER_virtual/kernel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;linux-raspberrypi&quot;</span></span></code></pre></div><hr><h2 id="_2-using-menuconfig" tabindex="-1">2. Using <code>menuconfig</code> <a class="header-anchor" href="#_2-using-menuconfig" aria-label="Permalink to &quot;2. Using \`menuconfig\`&quot;">​</a></h2><p>The Linux Kernel is the most configurable piece of software on the planet. There are over 15,000 different settings (drivers, network protocols, filesystems) you can toggle on or off.</p><p>These settings are stored in a hidden file called <code>.config</code> inside the kernel build directory. To edit this file safely, the Linux Kernel provides a curses-based GUI tool called <code>menuconfig</code>.</p><p>In Yocto, you can launch this tool for your specific kernel using BitBake:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># We use the virtual provider name so we don&#39;t need to know if it&#39;s linux-yocto or linux-ti</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> menuconfig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> virtual/kernel</span></span></code></pre></div><h3 id="the-three-states-of-a-driver" tabindex="-1">The Three States of a Driver <a class="header-anchor" href="#the-three-states-of-a-driver" aria-label="Permalink to &quot;The Three States of a Driver&quot;">​</a></h3><p>When you navigate the menu, you will see options wrapped in brackets: <code>[ ]</code> or <code>&lt; &gt;</code>. Pressing the <strong>Spacebar</strong> cycles through the states:</p><ol><li><strong><code>[ ]</code> Disabled:</strong> The code for this driver will not be compiled. The feature will not exist on your device.</li><li><strong><code>[*] / &lt;*&gt;</code> Built-in (y):</strong> The driver is compiled <em>directly into the <code>zImage</code> kernel binary</em>. It is permanently loaded into RAM as soon as the system boots. Used for critical things (like the root filesystem driver or CPU scheduler).</li><li><strong><code>&lt;M&gt;</code> Module (m):</strong> The driver is compiled as a separate <code>.ko</code> (Kernel Object) file on the disk (e.g., in <code>/lib/modules/</code>). It is only loaded into RAM when you plug in the specific hardware (like a USB Wi-Fi dongle). This saves RAM but slows down boot time slightly.</li></ol><hr><h2 id="_3-creating-kernel-configuration-fragments" tabindex="-1">3. Creating Kernel Configuration Fragments <a class="header-anchor" href="#_3-creating-kernel-configuration-fragments" aria-label="Permalink to &quot;3. Creating Kernel Configuration Fragments&quot;">​</a></h2><p>Just like BusyBox, if you make changes in <code>menuconfig</code> and then run <code>bitbake -c clean virtual/kernel</code>, your changes are permanently destroyed.</p><p>You must save your changes to a <code>.cfg</code> file (Configuration Fragment) in your custom layer.</p><h3 id="step-1-isolate-your-changes" tabindex="-1">Step 1: Isolate your changes <a class="header-anchor" href="#step-1-isolate-your-changes" aria-label="Permalink to &quot;Step 1: Isolate your changes&quot;">​</a></h3><p>Let&#39;s say you enabled the <code>CAN</code> bus networking protocol in <code>menuconfig</code>. The <code>menuconfig</code> tool actually modifies the <code>.config</code> file to say:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONFIG_CAN=m</span></span>
<span class="line"><span>CONFIG_CAN_RAW=m</span></span>
<span class="line"><span>CONFIG_CAN_BCM=m</span></span></code></pre></div><p>Instead of saving the entire 15,000-line <code>.config</code> file (which is a maintenance nightmare when upgrading to a newer kernel), you create a tiny text file containing <em>only the lines you changed</em>.</p><p>Create a file named <code>enable-canbus.cfg</code> inside your custom layer (<code>meta-custom/recipes-kernel/linux/files/</code>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># enable-canbus.cfg</span></span>
<span class="line"><span>CONFIG_CAN=m</span></span>
<span class="line"><span>CONFIG_CAN_RAW=m</span></span>
<span class="line"><span>CONFIG_CAN_BCM=m</span></span></code></pre></div><h3 id="step-2-write-the-bbappend" tabindex="-1">Step 2: Write the <code>.bbappend</code> <a class="header-anchor" href="#step-2-write-the-bbappend" aria-label="Permalink to &quot;Step 2: Write the \`.bbappend\`&quot;">​</a></h3><p>Create a <code>.bbappend</code> for the kernel recipe. If you are building for QEMU (<code>linux-yocto</code>), the append must match that name.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># meta-custom/recipes-kernel/linux/linux-yocto_%.bbappend</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Tell BitBake where to find the fragment</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">FILESEXTRAPATHS:prepend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">THISDIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/files:&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add the fragment to the SRC_URI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SRC_URI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;file://enable-canbus.cfg&quot;</span></span></code></pre></div><p>When BitBake builds the kernel, it will take the default upstream <code>.config</code> file and merge your <code>.cfg</code> fragment over the top of it.</p><hr><h2 id="_4-hands-on-lab-exercises" tabindex="-1">4. Hands-On Lab Exercises <a class="header-anchor" href="#_4-hands-on-lab-exercises" aria-label="Permalink to &quot;4. Hands-On Lab Exercises&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">LAB 19.1: Enable a USB Ethernet Driver</p><p>Let&#39;s simulate needing support for a specific USB-to-Ethernet adapter.</p><ol><li>Run <code>bitbake -c menuconfig virtual/kernel</code>.</li><li>Press <code>/</code> to open the search bar. Search for <code>USB_RTL8152</code>.</li><li>The search results will show you exactly which menu path to navigate to find the driver (usually under Device Drivers -&gt; Network device support -&gt; USB Network Adapters).</li><li>Navigate there and press <strong>M</strong> to compile the Realtek RTL8152 driver as a module (<code>&lt;M&gt;</code>).</li><li>Save and Exit.</li></ol></div><div class="tip custom-block"><p class="custom-block-title">LAB 19.2: Generate a Fragment Automatically</p><p>Instead of manually typing out <code>.cfg</code> files, Yocto provides a tool to calculate the exact difference between the default kernel config and your new modifications.</p><ol><li>Make sure you saved your changes in Lab 19.1.</li><li>Run <code>bitbake -c diffconfig virtual/kernel</code>.</li><li>BitBake will print the path to a newly generated <code>fragment.cfg</code> file containing only your <code>CONFIG_USB_RTL8152=m</code> change!</li><li>You can copy this file into your layer.</li></ol></div><hr><h2 id="_5-further-reading" tabindex="-1">5. Further Reading <a class="header-anchor" href="#_5-further-reading" aria-label="Permalink to &quot;5. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Kernel Configuration in Yocto</td><td><a href="https://docs.yoctoproject.org/kernel-dev/common.html#changing-the-configuration" target="_blank" rel="noreferrer">docs.yoctoproject.org/kernel-dev/common.html#changing-the-configuration</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day18-device-trees-dts-dtb-dtc">← Day 18: Device Trees</a><a href="/day20-uboot-tftp-nfs-booting">Day 20: U-Boot &amp; Network Booting →</a></div>`,41)])])}const g=a(s,[["render",o]]);export{u as __pageData,g as default};
